SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.discharge_location, COUNT(a.hadm_id) AS num_admissions, AVG(a.los) AS avg_los, MEDIAN(a.los) AS median_los, SUM(CASE WHEN a.discharge_location = 'ED' AND p.dod IS NULL THEN 1 ELSE 0 END) AS alive_discharges, SUM(CASE WHEN a.discharge_location = 'ED' AND p.dod IS NOT NULL THEN 1 ELSE 0 END) AS mortality_discharges, CAST(SUM(CASE WHEN a.los <= 5 THEN 1 ELSE 0 END) AS FLOAT) / NULLIF(COUNT(a.hadm_id), 0) AS pct_los_5_or_less FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 41 AND 51 AND a.admission_type = 'ED' GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.discharge_location;